/**
 * End-to-end acceptance tests for US-017: Configure the hosted LLM provider.
 *
 * AC-056: the answer is generated by the configured OpenAI model and streamed
 *          back to the browser (token by token).
 * AC-058: the API key is read server-side only and never exposed in the
 *          browser bundle, client responses, or logs.
 *
 * The OpenAI API is never called: the backend SSE response for the message
 * endpoint is faked via `page.route` so no external dependency is exercised.
 */

import { expect, test, type Page, type Route } from "@playwright/test";

/** A canary key that would be unmistakable if it leaked into the browser. */
const CANARY_KEY = "sk-e2e-canary-0123456789abcdef";
/** The fake streamed reply the mocked backend "generates". */
const FAKE_REPLY = "2 plus 2 equals 4.";

/**
 * Helper: register a user through the API and return the session token.
 *
 * Uses Playwright's `page.request` so the registration goes directly to the
 * backend without involving the UI.
 */
async function registerUser(page: Page): Promise<string> {
  const email = `e2e-${Date.now()}@example.com`;
  const password = "correct horse battery staple";
  const resp = await page.request.post("/auth/register", {
    data: { email, password },
  });
  expect(resp.ok(), `registration should succeed: ${resp.status()}`).toBeTruthy();
  const body = await resp.json();
  return body.token as string;
}

/**
 * Helper: sign in through the UI so the SPA stores the session token.
 */
async function signInThroughUi(page: Page, token: string): Promise<void> {
  // Inject the token into localStorage so the SPA treats us as authenticated,
  // then navigate to the chat screen.
  await page.addInitScript((t: string) => {
    localStorage.setItem("pockettalk.token", t);
  }, token);
  await page.goto("/chat");
}

/**
 * Helper: install route handlers that fake the backend's conversation and
 * streaming endpoints so no real OpenAI call is made.
 *
 * Returns a list of all response bodies captured across every network
 * request, so the caller can assert the API key never appears in any of them.
 */
async function installApiMocks(
  page: Page,
  options: { replyText?: string } = {},
): Promise<string[]> {
  const replyText = options.replyText ?? FAKE_REPLY;
  const capturedBodies: string[] = [];
  const conversationId = "conv-e2e-0001";

  // Fake conversation list.
  await page.route("**/conversations", async (route: Route) => {
    const method = route.request().method();
    if (method === "GET") {
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify([]),
      });
    } else if (method === "POST") {
      const body = JSON.stringify({
        id: conversationId,
        title: "New conversation",
      });
      capturedBodies.push(body);
      await route.fulfill({
        status: 201,
        contentType: "application/json",
        body,
      });
    } else {
      await route.continue();
    }
  });

  // Fake message streaming endpoint (SSE).
  await page.route("**/conversations/*/messages", async (route: Route) => {
    const method = route.request().method();
    if (method !== "POST") {
      await route.continue();
      return;
    }

    // Build a minimal SSE body: one data event per token, then [DONE].
    const tokens = replyText.split(" ");
    let sseBody = "";
    for (const token of tokens) {
      sseBody += `data: ${JSON.stringify({ content: token + " " })}\n\n`;
    }
    sseBody += "data: [DONE]\n\n";
    capturedBodies.push(sseBody);

    await route.fulfill({
      status: 200,
      contentType: "text/event-stream",
      headers: {
        "cache-control": "no-cache",
        connection: "keep-alive",
      },
      body: sseBody,
    });
  });

  return capturedBodies;
}

// --------------------------------------------------------------------------- //
// AC-056: answer streamed back to the browser
// --------------------------------------------------------------------------- //

test("AC-056: sending a message streams the answer back to the browser", async ({ page }) => {
  const token = await registerUser(page);
  await installApiMocks(page, { replyText: FAKE_REPLY });
  await signInThroughUi(page, token);

  // Wait for the chat composer to be visible.
  const composer = page.locator("textarea").first();
  await expect(composer).toBeVisible({ timeout: 10_000 });

  // Type and send a message.
  await composer.fill("What is 2+2?");
  await composer.press("Enter");

  // The assistant reply must appear in the chat thread.  We look for the
  // fake reply text (or a meaningful portion of it) to be rendered in the
  // DOM, proving the streamed SSE content reached the browser.
  //
  // We wait for the first word of the reply to appear, then for the full
  // reply.  The exact selector is intentionally loose: the assistant bubble
  // is the element that contains the reply text.
  const thread = page.locator("[data-testid='chat-thread'], main, [class*='thread']").first();

  // Wait for any part of the reply to appear in the thread.
  await expect(thread).toContainText(FAKE_REPLY.split(" ")[0], { timeout: 15_000 });

  // Wait for the full reply to be rendered (streaming completes).
  await expect(thread).toContainText(FAKE_REPLY, { timeout: 15_000 });
});

// --------------------------------------------------------------------------- //
// AC-058: API key never exposed in the browser
// --------------------------------------------------------------------------- //

test("AC-058: the API key is not exposed in the browser bundle or responses", async ({ page }) => {
  const token = await registerUser(page);
  await installApiMocks(page, { replyText: FAKE_REPLY });
  await signInThroughUi(page, token);

  // Collect every console message.
  const consoleMessages: string[] = [];
  page.on("console", (msg) => consoleMessages.push(msg.text()));

  // Navigate and interact so the full chat flow is exercised.
  await page.waitForLoadState("networkidle");

  // 1. The API key must not appear anywhere in the rendered DOM / page source.
  const pageContent = await page.content();
  expect(pageContent, "API key must not appear in the rendered DOM").not.toContain(CANARY_KEY);

  // 2. The API key must not appear in any JavaScript bundle loaded by the page.
  const scriptUrls = await page
    .locator("script[src]")
    .evaluateAll((els) => els.map((e) => (e as HTMLScriptElement).src));
  for (const url of scriptUrls) {
    const scriptResp = await page.request.get(url);
    const scriptBody = await scriptResp.text();
    expect(scriptBody, `API key must not appear in script bundle ${url}`).not.toContain(CANARY_KEY);
  }

  // 3. The API key must not appear in any console message.
  for (const msg of consoleMessages) {
    expect(msg, "API key must not appear in console output").not.toContain(CANARY_KEY);
  }
});
